      const points = rows.map(([calls, total_us, mean_us, p50_us, p95_us, core, coverage, measured_calls, values], index) => ({
        batch: index + 1,
        calls, total_us, mean_us, p50_us, p95_us, core,
        pipeline: { coverage, measured_calls, scores: Object.fromEntries(values.map((value, i) => [pipelineNames[i], value])) },
      }));
      kernels.push({ name, points });
